import java.io.ByteArrayOutputStream;
import java.io.ObjectOutputStream;
import java.util.Base64;

public class VersionGuardLoaderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static byte[] serialize(Object value) {
        try {
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
                out.writeObject(value);
            }
            return bytes.toByteArray();
        } catch (Exception e) {
            return new byte[0];
        }
    }

    // Written by a Settings class whose serialVersionUID was 99L.
    static final String OLD_SETTINGS =
        "rO0ABXNyAAhTZXR0aW5ncwAAAAAAAABjAgACSQAIZm9udFNpemVMAAV0aGVtZXQAEkxqYXZhL2xhbmcvU3RyaW5nO3hwAAAADnQABGRhcms=";
    // Written by a class named GhostPayload that does not exist here.
    static final String GHOST =
        "rO0ABXNyAAxHaG9zdFBheWxvYWQAAAAAAAAAAQIAAUwABG5vdGV0ABJMamF2YS9sYW5nL1N0cmluZzt4cHQAA2Jvbw==";

    static String safeLoad(byte[] data) {
        try {
            return VersionGuardLoader.load(data);
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        byte[] good = serialize(new Settings("dark", 14));
        check("good bytes", "ok:dark:14", safeLoad(good));
        check("other good bytes", "ok:light:9", safeLoad(serialize(new Settings("light", 9))));
        check("old serialVersionUID", "version-mismatch", safeLoad(Base64.getDecoder().decode(OLD_SETTINGS)));
        check("class not on the classpath", "unknown-class", safeLoad(Base64.getDecoder().decode(GHOST)));
        check("a String instead of Settings", "wrong-type", safeLoad(serialize("not settings")));

        byte[] truncated = new byte[12];
        System.arraycopy(good, 0, truncated, 0, 12);
        check("truncated stream", "corrupt", safeLoad(truncated));
        check("garbage bytes", "corrupt", safeLoad(new byte[] {1, 2, 3, 4, 5, 6}));
        check("empty array", "corrupt", safeLoad(new byte[0]));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

